    radial-gradient(1.5px 1.5px at 40% 60%, rgba(255,255,255,0.35) 0%, transparent 100%),
    radial-gradient(1px 1px at 80% 72%, rgba(255,255,255,0.45) 0%, transparent 100%),
    radial-gradient(1px 1px at 15% 78%, rgba(255,255,255,0.3) 0%, transparent 100%),
    radial-gradient(1px 1px at 50% 88%, rgba(255,255,255,0.35) 0%, transparent 100%);
}
[data-theme="light"] .hero-stars { display: none; }

.hero-content {
  position: relative;
  z-index: 1;
  display: flex;
  align-items: center;
  gap: 64px;
  max-width: 1100px;
  width: 100%;
  padding: 0 28px;
  padding-bottom: 40px;
}

.hero-avatar {
  position: relative;
  flex-shrink: 0;
}
.avatar-img {
  width: 180px;
  height: 180px;
  border-radius: 50%;
  object-fit: cover;
  border: 3px solid var(--color-primary);
  box-shadow: 0 0 0 8px rgba(0, 200, 180, 0.10), var(--shadow-lg);
  transition: transform var(--transition), box-shadow var(--transition);
}
.avatar-img:hover {
  transform: scale(1.03);
  box-shadow: 0 0 0 10px rgba(0, 200, 180, 0.15), var(--shadow-glow);
}
.avatar-ring {
  position: absolute;
  inset: -12px;
  border-radius: 50%;
  border: 1px solid rgba(0, 200, 180, 0.25);
  animation: pulse 3s ease-in-out infinite;
}
@keyframes pulse {
  0%, 100% { transform: scale(1); opacity: 0.5; }
  50%       { transform: scale(1.05); opacity: 0.2; }
}

.hero-text {
  flex: 1;
  min-width: 0;
}
.hero-pre {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  font-size: 0.82rem;
  font-weight: 600;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  color: var(--color-primary);
  margin-bottom: 14px;
}
.hero-pre::before {
  content: '';
  display: inline-block;
  width: 28px;
  height: 2px;
  background: var(--color-primary);
  border-radius: 2px;
}

.hero-name {
  font-family: var(--font-display);
  font-size: clamp(2.4rem, 5vw, 4rem);
  font-weight: 700;
  line-height: 1.1;
  color: var(--color-text);
  margin-bottom: 18px;
  letter-spacing: -0.02em;
}
.hero-name-accent {
  color: var(--color-primary);
}
[data-theme="light"] .hero-name { color: #0d1e38; }

.hero-affiliation {
  display: flex;
  align-items: flex-start;
  gap: 8px;
  font-size: 0.95rem;
  color: var(--color-text-muted);
  margin-bottom: 24px;
  line-height: 1.5;
}
.hero-affiliation svg {
  flex-shrink: 0;
  margin-top: 2px;
  color: var(--color-accent);
}

.hero-tags {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
  margin-bottom: 32px;
}
.hero-tag {
  padding: 5px 13px;
  border-radius: var(--radius-full);
  font-size: 0.78rem;
  font-weight: 600;
  letter-spacing: 0.02em;
  background: var(--color-surface-2);
  border: 1px solid var(--color-border);
  color: var(--color-text-muted);
  transition: all var(--transition);
}
.hero-tag:hover {
  background: var(--color-primary-light);
  border-color: var(--color-primary);
  color: var(--color-primary);
}

.hero-links {
  display: flex;
  flex-wrap: wrap;
  gap: 10px;
}

.scroll-down {
  position: absolute;
  bottom: 32px;
  left: 50%;
  transform: translateX(-50%);
  color: var(--color-text-faint);
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 6px;
  font-size: 0.72rem;
  font-weight: 600;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  text-decoration: none;
  animation: bounce 2.5s ease-in-out infinite;
  transition: color var(--transition);
  z-index: 1;
}
.scroll-down:hover { color: var(--color-primary); text-decoration: none; }
@keyframes bounce {
  0%, 100% { transform: translateX(-50%) translateY(0); }
  50%       { transform: translateX(-50%) translateY(7px); }
}

/* =====================================================
   ABOUT
   ===================================================== */
.about-metrics {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 2px;
  margin-bottom: 64px;
  border: 1px solid var(--color-border);
  border-radius: var(--radius-lg);
  overflow: hidden;
  background: var(--color-border);
}

.metric-item {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  padding: 28px 16px;
  background: var(--color-surface);
  transition: background var(--transition);
  text-align: center;
}
.metric-item:hover { background: var(--color-surface-2); }

.metric-number {
  font-family: var(--font-mono);
  font-size: clamp(2rem, 3.5vw, 3rem);
  font-weight: 500;
  color: var(--color-primary);
  line-height: 1;
  margin-bottom: 8px;
  display: block;
}

.metric-label {
  font-size: 0.78rem;
  font-weight: 600;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: var(--color-text-muted);
}

.about-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 56px;
  align-items: start;
}

.about-text p {
  font-size: 1.025rem;
  line-height: 1.8;
  color: var(--color-text-muted);
  margin-bottom: 20px;
}
.about-text p:last-child { margin-bottom: 0; }

.about-highlights {
  display: flex;
  flex-direction: column;
  gap: 14px;
}

.highlight-card {
  display: flex;
  align-items: flex-start;
  gap: 16px;
  padding: 20px;
  background: var(--color-surface);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-md);
  transition: all var(--transition);
}
.highlight-card:hover {
  border-color: var(--color-primary);
  background: var(--color-surface-2);
  transform: translateX(4px);
  box-shadow: -3px 0 0 var(--color-primary), var(--shadow-md);
}

.highlight-icon-wrap {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 42px;
  height: 42px;
  border-radius: var(--radius-sm);
  background: var(--color-primary-light);
  color: var(--color-primary);
  flex-shrink: 0;
}

.highlight-card h3 {
  font-size: 0.95rem;
  font-weight: 600;
  color: var(--color-text);
  margin-bottom: 4px;
}
.highlight-card p {
  font-size: 0.875rem;
  color: var(--color-text-muted);
  line-height: 1.5;
}

/* =====================================================
   NEWS
   ===================================================== */
.news-grid {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 20px;
}

.news-card {
  display: flex;
  gap: 16px;
  align-items: flex-start;
  padding: 20px 22px;
  background: var(--color-surface);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-md);
  transition: all var(--transition);
  cursor: default;
}
