  border-color: var(--color-border-strong);
  background: var(--color-surface-2);
  transform: translateY(-2px);
  box-shadow: var(--shadow-md);
}

.news-date {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  min-width: 52px;
  padding: 8px 6px;
  background: var(--color-surface-2);
  border-radius: var(--radius-sm);
  flex-shrink: 0;
  text-align: center;
}
.news-date-month {
  font-size: 0.65rem;
