  padding: 40px 0;
}

.footer-inner {
  max-width: 1100px;
  margin: 0 auto;
  padding: 0 28px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 20px;
  flex-wrap: wrap;
}

.footer-copy {
  font-size: 0.85rem;
  color: var(--color-text-muted);
}
.footer-copy span { color: var(--color-primary); }

.footer-links {
  display: flex;
  gap: 20px;
}
.footer-links a {
  font-size: 0.82rem;
  color: var(--color-text-muted);
  text-decoration: none;
  transition: color var(--transition);
}
.footer-links a:hover {
  color: var(--color-primary);
  text-decoration: none;
}

