  border: 1px solid var(--color-border);
  border-radius: var(--radius-lg);
  overflow: hidden;
}
.flowcv-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 16px 24px;
  border-bottom: 1px solid var(--color-border);
  flex-wrap: wrap;
  gap: 10px;
}
.flowcv-title {
  font-family: var(--font-display);
  font-size: 1rem;
  font-weight: 600;
  color: var(--color-text);
  margin: 0;
}
.flowcv-actions { display: flex; gap: 8px; flex-wrap: wrap; }
.flowcv-frame-wrap {
  position: relative;
  width: 100%;
  height: 700px;
}
.flowcv-iframe {
  width: 100%;
  height: 100%;
  border: none;
  display: block;
}
.flowcv-fallback {
  display: none;
  position: absolute;
  inset: 0;
  background: var(--color-surface-2);
  align-items: center;
  justify-content: center;
  flex-direction: column;
  gap: 12px;
  text-align: center;
  color: var(--color-text-muted);
  font-size: 0.9rem;
  padding: 24px;
}
.flowcv-wrap--error .flowcv-fallback { display: flex; }
.flowcv-wrap--error .flowcv-iframe   { display: none; }

@media (max-width: 640px) {
  .flowcv-frame-wrap { height: 480px; }
}

/* =====================================================
   SEE MORE / COLLAPSE
   ===================================================== */
.see-more-wrap {
  text-align: center;
  margin-top: 24px;
}
.see-more-btn {
  display: inline-flex;
  align-items: center;
  gap: 7px;
  padding: 10px 26px;
  border-radius: var(--radius-full);
  font-size: 0.855rem;
  font-weight: 600;
  font-family: var(--font-sans);
  background: var(--color-surface);
  border: 1px solid var(--color-border);
  color: var(--color-text-muted);
  cursor: pointer;
  transition: all var(--transition);
  letter-spacing: 0.01em;
}
.see-more-btn:hover {
  background: var(--color-surface-2);
  border-color: var(--color-primary);
  color: var(--color-primary);
}
.see-more-icon {
  transition: transform var(--transition);
  flex-shrink: 0;
}

/* =====================================================
   FOOTER SOCIAL STRIP
   ===================================================== */
.footer-inner {
  flex-direction: column;
  align-items: flex-start;
  gap: 16px;
}
.footer-top-row {
  display: flex;
  align-items: center;
  justify-content: space-between;
  width: 100%;
  gap: 20px;
  flex-wrap: wrap;
}
.footer-socials {
  display: flex;
  align-items: center;
  gap: 8px;
  flex-wrap: wrap;
}
.footer-social-link {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 32px;
  height: 32px;
  border-radius: 50%;
  border: 1px solid var(--color-border);
  color: var(--color-text-muted);
  transition: all var(--transition);
  text-decoration: none;
}
.footer-social-link:hover {
  border-color: var(--color-primary);
  color: var(--color-primary);
  background: var(--color-primary-light);
  text-decoration: none;
}

